

'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Button } from '@/components/ui/button';
import { MoreHorizontal, ListFilter, Search, Building, Trash2, Edit } from 'lucide-react';
import { useRouter } from 'next/navigation';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { cn } from '@/lib/utils';
import type { VariantProps } from 'class-variance-authority';
import { format, parseISO } from 'date-fns';
import { useToast } from '@/hooks/use-toast';
import { supabase } from '@/lib/supabase/client';
import { StoredApplication } from '../applications/[id]/page';

type ApplicationStatus = 'Pending' | 'Approved' | 'Rejected';

const badgeVariantsForStatus = ({ status }: { status: ApplicationStatus }) => {
  return {
    variant: (
      status === 'Approved' ? 'default' :
      status === 'Rejected' ? 'destructive' :
      status === 'Pending' ? 'secondary' :
      'default'
    ) as "default" | "destructive" | "secondary" | "outline" | null | undefined,
  };
};

interface StatusBadgeProps extends VariantProps<typeof badgeVariantsForStatus> {
  status: ApplicationStatus;
  className?: string;
}

const StatusBadge: React.FC<StatusBadgeProps> = ({ status, className }) => {
  const { variant } = badgeVariantsForStatus({ status });
  return <Badge variant={variant} className={cn("capitalize", className)}>{status}</Badge>;
};


const PERMIT_TYPES = [
    "Building Permit (Individual)",
    "Building Permit (Organization)",
    "Mast Installation Permit",
    "Outdoor Advertisement Permit",
    "Outdoor Structure Permit",
    "Temporary Shop Owners Permit",
    "Street Naming Permit",
];

export default function PermitApplicationsPage() {
  const router = useRouter();
  const { toast } = useToast();
  const [applications, setApplications] = useState<StoredApplication[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<ApplicationStatus | 'All'>('All');
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [applicationToDelete, setApplicationToDelete] = useState<StoredApplication | null>(null);
  
  const loadApplications = React.useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('applications')
        .select('*')
        .in('type', PERMIT_TYPES)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setApplications(data as StoredApplication[]);
    } catch (error) {
      console.error("Error fetching permit applications from Supabase:", error);
      toast({
        title: "Error",
        description: "Failed to load permit applications from the database.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, [toast]);

  useEffect(() => {
    loadApplications();
  }, [loadApplications]);

  const handleViewDetails = (appId: string) => {
    router.push(`/admin/applications/${appId}`);
  };

  const handleEdit = (appId: string) => {
    router.push(`/admin/applications/edit/${appId}`);
  };

  const openDeleteDialog = (app: StoredApplication) => {
    setApplicationToDelete(app);
    setIsDeleteDialogOpen(true);
  };

  const handleDelete = async () => {
    if (!applicationToDelete) return;

    try {
        const { error } = await supabase
            .from('applications')
            .delete()
            .eq('id', applicationToDelete.id);

        if (error) throw error;
        
        setApplications(prev => prev.filter(app => app.id !== applicationToDelete.id));
        toast({
            title: "Application Deleted",
            description: `Application ID (${applicationToDelete.data.applicationId || applicationToDelete.id}) has been deleted.`,
        });
    } catch (error) {
        console.error("Error deleting application:", error);
        toast({
            title: 'Error',
            description: 'Could not delete the application from the database.',
            variant: 'destructive',
        });
    } finally {
        setIsDeleteDialogOpen(false);
        setApplicationToDelete(null);
    }
  };

  const handleStatusChange = async (appId: string, appCustomId: string, newStatus: ApplicationStatus) => {
     if (newStatus === 'Rejected') {
      router.push(`/admin/applications/${appId}?action=reject`);
      return;
    }
     try {
        const { error } = await supabase
            .from('applications')
            .update({ status: newStatus, rejection_reason: null })
            .eq('id', appId);

        if (error) throw error;
        
        setApplications(prevApps => 
            prevApps.map(app => 
                app.id === appId ? { ...app, status: newStatus } : app
            )
        );

        toast({
            title: `Application ${newStatus}`,
            description: `The application (${appCustomId}) has been marked as ${newStatus}.`
        });
    } catch (error) {
        console.error("Error updating status:", error);
        toast({
            title: 'Error',
            description: 'Could not update the application status in the database.',
            variant: 'destructive',
        });
    }
  };

  const filteredApplications = applications.filter(app => {
    const termMatch = searchTerm.trim() === '' || 
        app.applicant_name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        (app.data?.applicationId || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        app.id.toLowerCase().includes(searchTerm.toLowerCase());
    
    const statusMatch = statusFilter === 'All' || app.status === statusFilter;

    return termMatch && statusMatch;
  });

  return (
    <div className="space-y-8">
      <Card>
        <CardHeader>
          <div className="flex items-center gap-3">
            <Building className="h-6 w-6 text-primary" />
            <div>
              <CardTitle>Permit Applications</CardTitle>
              <CardDescription>Manage all submitted building, temporary, and other permit applications.</CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between gap-4 mb-6">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input 
                placeholder="Search by applicant name or ID..." 
                className="pl-10" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" className="gap-2">
                  <ListFilter className="h-4 w-4" />
                  Filter ({statusFilter})
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuLabel>Filter by Status</DropdownMenuLabel>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => setStatusFilter('All')}>All</DropdownMenuItem>
                <DropdownMenuItem onClick={() => setStatusFilter('Pending')}>Pending</DropdownMenuItem>
                <DropdownMenuItem onClick={() => setStatusFilter('Approved')}>Approved</DropdownMenuItem>
                <DropdownMenuItem onClick={() => setStatusFilter('Rejected')}>Rejected</DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
          
          <div className="border rounded-md">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Application ID</TableHead>
                  <TableHead>Applicant</TableHead>
                  <TableHead>Type</TableHead>
                  <TableHead>Date Submitted</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                    <TableRow>
                        <TableCell colSpan={6} className="h-24 text-center">
                            Loading permit applications...
                        </TableCell>
                    </TableRow>
                ) : filteredApplications.length > 0 ? (
                  filteredApplications.map((app) => (
                    <TableRow key={app.id}>
                      <TableCell className="font-medium text-xs">{app.data.applicationId || app.id}</TableCell>
                      <TableCell>{app.applicant_name}</TableCell>
                      <TableCell className="text-sm">{app.type}</TableCell>
                      <TableCell>{app.created_at ? format(parseISO(app.created_at), 'dd/MM/yyyy') : 'N/A'}</TableCell>
                      <TableCell>
                        <StatusBadge status={app.status as ApplicationStatus} />
                      </TableCell>
                      <TableCell className="text-right">
                         <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" className="h-8 w-8 p-0">
                              <span className="sr-only">Open menu</span>
                              <MoreHorizontal className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuLabel>Actions</DropdownMenuLabel>
                            <DropdownMenuItem onClick={() => handleViewDetails(app.id)}>
                              View Details
                            </DropdownMenuItem>
                             <DropdownMenuItem onClick={() => handleEdit(app.id)}>
                              <Edit className="mr-2 h-4 w-4" /> Edit Application
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem onClick={() => handleStatusChange(app.id, app.data.applicationId || app.id, 'Approved')}>Approve</DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleStatusChange(app.id, app.data.applicationId || app.id, 'Rejected')}>Reject</DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleStatusChange(app.id, app.data.applicationId || app.id, 'Pending')}>Set to Pending</DropdownMenuItem>
                             <DropdownMenuSeparator />
                            <DropdownMenuItem onClick={() => openDeleteDialog(app)} className="text-destructive">
                               <Trash2 className="mr-2 h-4 w-4" /> Delete Application
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableRow>
                    <TableCell colSpan={6} className="h-24 text-center">
                      No permit applications found.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>
      <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Are you absolutely sure?</AlertDialogTitle>
            <AlertDialogDescription>
              This action cannot be undone. This will permanently delete the application
              for <span className="font-semibold">{applicationToDelete?.applicant_name}</span> (ID: {applicationToDelete?.data.applicationId || applicationToDelete?.id}).
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
